"use client";

import { useState } from "react";
import { Network, Info, ArrowRight, Eye, RefreshCw, ZoomIn, ZoomOut } from "lucide-react";

interface Node {
  id: string;
  label: string;
  type: "page" | "layout" | "component" | "lib";
  size: number;
  cx: number;
  cy: number;
  imports: string[];
}

interface Link {
  source: string;
  target: string;
}

export default function DependencyGraph() {
  const [selectedNode, setSelectedNode] = useState<string>("app/workspace/page.tsx");
  const [zoom, setZoom] = useState(1);
  const [hoveredNode, setHoveredNode] = useState<string | null>(null);

  const nodes: Node[] = [
    { id: "app/layout.tsx", label: "layout.tsx", type: "layout", size: 28, cx: 300, cy: 80, imports: ["app/globals.css"] },
    { id: "app/globals.css", label: "globals.css", type: "lib", size: 18, cx: 480, cy: 80, imports: [] },
    { id: "app/workspace/page.tsx", label: "page.tsx (workspace)", type: "page", size: 30, cx: 300, cy: 220, imports: ["components/layout/WorkspaceLayout.tsx"] },
    { id: "components/layout/WorkspaceLayout.tsx", label: "WorkspaceLayout.tsx", type: "layout", size: 26, cx: 300, cy: 360, imports: ["components/workspace/DependencyGraph.tsx", "components/workspace/AiAssistant.tsx", "components/workspace/RepositoryOverview.tsx"] },
    { id: "components/workspace/DependencyGraph.tsx", label: "DependencyGraph.tsx", type: "component", size: 22, cx: 120, cy: 450, imports: ["lib/utils.ts"] },
    { id: "components/workspace/AiAssistant.tsx", label: "AiAssistant.tsx", type: "component", size: 22, cx: 300, cy: 500, imports: ["lib/utils.ts"] },
    { id: "components/workspace/RepositoryOverview.tsx", label: "RepositoryOverview.tsx", type: "component", size: 22, cx: 480, cy: 450, imports: ["lib/utils.ts"] },
    { id: "lib/utils.ts", label: "utils.ts", type: "lib", size: 16, cx: 300, cy: 620, imports: [] }
  ];

  const links: Link[] = [
    { source: "app/layout.tsx", target: "app/globals.css" },
    { source: "app/workspace/page.tsx", target: "components/layout/WorkspaceLayout.tsx" },
    { source: "components/layout/WorkspaceLayout.tsx", target: "components/workspace/DependencyGraph.tsx" },
    { source: "components/layout/WorkspaceLayout.tsx", target: "components/workspace/AiAssistant.tsx" },
    { source: "components/layout/WorkspaceLayout.tsx", target: "components/workspace/RepositoryOverview.tsx" },
    { source: "components/workspace/DependencyGraph.tsx", target: "lib/utils.ts" },
    { source: "components/workspace/AiAssistant.tsx", target: "lib/utils.ts" },
    { source: "components/workspace/RepositoryOverview.tsx", target: "lib/utils.ts" }
  ];

  const activeNodeData = nodes.find((n) => n.id === selectedNode) || nodes[2];

  // Helper to find links connected to the active/hovered node
  const isLinkHighlight = (link: Link) => {
    const focusNode = hoveredNode || selectedNode;
    return link.source === focusNode || link.target === focusNode;
  };

  return (
    <div className="h-full flex flex-col lg:flex-row bg-card rounded-xl border border-border overflow-hidden shadow-sm">
      {/* Graph Visual Canvas */}
      <div className="flex-1 relative bg-muted/10 min-h-[450px] lg:min-h-0 flex flex-col justify-between p-4">
        {/* Graph Header */}
        <div className="flex items-center justify-between z-10">
          <div className="space-y-1">
            <h2 className="text-[15px] font-serif font-medium text-foreground flex items-center gap-2">
              <Network className="size-4 text-rust" />
              Interactive Dependency Graph
            </h2>
            <p className="text-xs text-muted-foreground">Visual imports mapping for codebase files.</p>
          </div>

          <div className="flex items-center gap-1.5 bg-card border border-border p-1 rounded-lg shadow-sm">
            <button 
              onClick={() => setZoom(prev => Math.min(prev + 0.1, 1.5))}
              className="p-1.5 hover:bg-muted rounded text-muted-foreground hover:text-foreground transition-colors"
              title="Zoom In"
            >
              <ZoomIn className="size-3.5" />
            </button>
            <button 
              onClick={() => setZoom(prev => Math.max(prev - 0.1, 0.6))}
              className="p-1.5 hover:bg-muted rounded text-muted-foreground hover:text-foreground transition-colors"
              title="Zoom Out"
            >
              <ZoomOut className="size-3.5" />
            </button>
            <button 
              onClick={() => { setZoom(1); setSelectedNode("app/workspace/page.tsx"); }}
              className="p-1.5 hover:bg-muted rounded text-muted-foreground hover:text-foreground transition-colors"
              title="Reset View"
            >
              <RefreshCw className="size-3.5" />
            </button>
          </div>
        </div>

        {/* SVG Drawing Canvas */}
        <div className="absolute inset-0 flex items-center justify-center overflow-hidden">
          <svg
            className="w-full h-full select-none cursor-grab active:cursor-grabbing transition-transform duration-300"
            style={{ transform: `scale(${zoom})` }}
            viewBox="0 0 600 700"
          >
            {/* Draw Links */}
            {links.map((link, idx) => {
              const sourceNode = nodes.find((n) => n.id === link.source);
              const targetNode = nodes.find((n) => n.id === link.target);
              if (!sourceNode || !targetNode) return null;

              const highlighted = isLinkHighlight(link);
              return (
                <line
                  key={`l-${idx}`}
                  x1={sourceNode.cx}
                  y1={sourceNode.cy}
                  x2={targetNode.cx}
                  y2={targetNode.cy}
                  stroke={highlighted ? "var(--rust)" : "var(--border)"}
                  strokeWidth={highlighted ? 2 : 1}
                  strokeDasharray={highlighted ? "4 2" : "none"}
                  className="transition-all duration-300"
                />
              );
            })}

            {/* Draw Nodes */}
            {nodes.map((node) => {
              const isSelected = selectedNode === node.id;
              const isHovered = hoveredNode === node.id;
              const isRelated = activeNodeData.id === node.id || activeNodeData.imports.includes(node.id) || links.some(l => l.source === node.id && l.target === activeNodeData.id);

              return (
                <g
                  key={node.id}
                  className="cursor-pointer group"
                  onClick={() => setSelectedNode(node.id)}
                  onMouseEnter={() => setHoveredNode(node.id)}
                  onMouseLeave={() => setHoveredNode(null)}
                >
                  <circle
                    cx={node.cx}
                    cy={node.cy}
                    r={node.size / 2 + 4}
                    fill={isSelected ? "var(--rust-light)" : "var(--card)"}
                    stroke={isSelected ? "var(--rust)" : isHovered ? "var(--rust-light)" : "var(--border)"}
                    strokeWidth={isSelected ? 2 : 1.5}
                    className="transition-all duration-300 drop-shadow-sm group-hover:scale-110"
                  />
                  <circle
                    cx={node.cx}
                    cy={node.cy}
                    r={4}
                    fill={isSelected ? "var(--rust)" : "var(--primary)"}
                  />
                  <text
                    x={node.cx}
                    y={node.cy + node.size / 2 + 16}
                    textAnchor="middle"
                    className={`text-[10px] font-mono select-none transition-all ${
                      isSelected
                        ? "fill-rust font-bold"
                        : isRelated
                        ? "fill-foreground font-medium"
                        : "fill-muted-foreground"
                    }`}
                  >
                    {node.label}
                  </text>
                </g>
              );
            })}
          </svg>
        </div>

        {/* Legend */}
        <div className="flex items-center gap-4 bg-card/60 backdrop-blur-sm border border-border p-2.5 rounded-lg text-[10px] font-mono text-muted-foreground z-10 self-start">
          <div className="flex items-center gap-1">
            <span className="size-2 rounded-full border border-border bg-card" />
            <span>Folder / Layout</span>
          </div>
          <div className="flex items-center gap-1">
            <span className="size-2 rounded-full bg-rust/35" />
            <span>Active Target</span>
          </div>
          <div className="flex items-center gap-1 animate-pulse">
            <span className="size-2 bg-rust rounded-full" />
            <span>Connected Imports</span>
          </div>
        </div>
      </div>

      {/* Inspector Panel */}
      <div className="w-full lg:w-[320px] border-t lg:border-t-0 lg:border-l border-border bg-card/50 backdrop-blur-sm p-5 flex flex-col justify-between">
        <div className="space-y-6">
          <div className="flex items-center justify-between border-b border-border/80 pb-3">
            <span className="text-[11px] font-mono text-muted-foreground uppercase tracking-widest">Selected Module</span>
            <span className="px-2 py-0.5 rounded bg-muted text-[10px] font-mono text-muted-foreground capitalize">{activeNodeData.type}</span>
          </div>

          <div className="space-y-2">
            <h3 className="text-base font-mono font-bold text-foreground truncate select-all">{activeNodeData.id}</h3>
            <p className="text-xs text-muted-foreground">
              This node is a {activeNodeData.type} module. Standard workspace analysis confirms its layout constraints.
            </p>
          </div>

          {/* Links Inspect */}
          <div className="space-y-4 pt-2">
            <div>
              <span className="text-[10px] font-mono text-muted-foreground uppercase tracking-wider block mb-2">Imports ({activeNodeData.imports.length})</span>
              {activeNodeData.imports.length === 0 ? (
                <p className="text-xs italic text-muted-foreground/80 pl-1">No imports declared</p>
              ) : (
                <div className="space-y-1.5">
                  {activeNodeData.imports.map((imp) => (
                    <div key={imp} className="flex items-center gap-2 text-xs bg-muted/40 p-2 rounded-lg border border-border/60 hover:border-rust/40 transition-colors">
                      <ArrowRight className="size-3 text-rust" />
                      <span className="font-mono text-foreground/80 truncate">{imp}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div>
              <span className="text-[10px] font-mono text-muted-foreground uppercase tracking-wider block mb-2">Dependents</span>
              {/* Find what nodes import this node */}
              {(() => {
                const dependents = nodes.filter(n => n.imports.includes(activeNodeData.id));
                return dependents.length === 0 ? (
                  <p className="text-xs italic text-muted-foreground/80 pl-1">No parent dependencies import this directly</p>
                ) : (
                  <div className="space-y-1.5">
                    {dependents.map((dep) => (
                      <div key={dep.id} className="flex items-center gap-2 text-xs bg-muted/40 p-2 rounded-lg border border-border/60">
                        <span className="size-1.5 bg-muted-foreground rounded-full" />
                        <span className="font-mono text-foreground/85 truncate">{dep.id}</span>
                      </div>
                    ))}
                  </div>
                );
              })()}
            </div>
          </div>
        </div>

        {/* Action button */}
        <div className="pt-6 border-t border-border/60">
          <button 
            onClick={() => alert(`Opening code context for: ${activeNodeData.id}`)}
            className="w-full flex items-center justify-center gap-2 py-2 px-3 bg-primary text-primary-foreground hover:bg-primary/90 text-xs font-medium rounded-lg transition-all shadow-sm"
          >
            <Eye className="size-3.5" />
            <span>Open Code Content</span>
          </button>
        </div>
      </div>
    </div>
  );
}
