"use client";

import { useState } from "react";
import { Send, Sparkles, MessageSquare, Terminal, Eye, FileText, CornerDownLeft } from "lucide-react";

interface Message {
  role: "user" | "assistant";
  content: string;
  codeSnippet?: {
    file: string;
    code: string;
    lang: string;
  };
  references?: string[];
}

export default function AiAssistant() {
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState<Message[]>([
    {
      role: "assistant",
      content: "Hello. I have fully indexed this workspace including **Next.js v16 App Router configuration**, local templates, and components. How can I assist your engineering work today?",
      references: ["CREATIVE_DIRECTION.md", "app/globals.css"]
    },
    {
      role: "user",
      content: "How are font variables injected in the layout file?"
    },
    {
      role: "assistant",
      content: "The font variables are configured using `next/font/google` and then injected in the `html` element's class list. This makes the variables available globally across Tailwind and standard CSS classes.",
      codeSnippet: {
        file: "app/layout.tsx",
        lang: "tsx",
        code: `import { Geist, Geist_Mono, Newsreader } from "next/font/google";

const newsreader = Newsreader({
  variable: "--font-serif",
  subsets: ["latin"],
});

export default function RootLayout({ children }) {
  return (
    <html lang="en" className={\`\${newsreader.variable} h-full\`}>
      <body>{children}</body>
    </html>
  );
}`
      },
      references: ["app/layout.tsx", "app/globals.css"]
    }
  ]);

  const handleSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMsg = input;
    setMessages((prev) => [...prev, { role: "user", content: userMsg }]);
    setInput("");

    // Simulate AI response after a short delay
    setTimeout(() => {
      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          content: `I've analyzed your question relative to the current workspace configuration. Based on the rules defined in [CREATIVE_DIRECTION.md](file:///c:/Users/LENOVO/OneDrive/Desktop/repomind-frontend/docs/CREATIVE_DIRECTION.md), everything uses off-white warm variables, and fonts are configured in [globals.css](file:///c:/Users/LENOVO/OneDrive/Desktop/repomind-frontend/app/globals.css). Let me know if you would like me to draft structural changes.`,
          references: ["docs/CREATIVE_DIRECTION.md", "app/globals.css"]
        }
      ]);
    }, 1000);
  };

  const quickActions = [
    "Explain project layout",
    "Analyze dependency path",
    "Draft component draft"
  ];

  return (
    <div className="h-full flex flex-col justify-between bg-card text-foreground flex-1 relative bg-grain">
      {/* Panel Header */}
      <div className="px-5 py-4 border-b border-border/80 flex items-center justify-between bg-card/65 backdrop-blur-sm z-10">
        <div className="flex items-center gap-2">
          <Sparkles className="size-4 text-rust" />
          <h2 className="text-[13.5px] font-serif font-semibold uppercase tracking-wider">AI Assistant</h2>
        </div>
        <span className="text-[10px] font-mono text-muted-foreground bg-muted px-2 py-0.5 rounded">Active Index</span>
      </div>

      {/* Messages Scroll Area */}
      <div className="flex-1 overflow-y-auto p-5 space-y-6">
        {messages.map((msg, idx) => (
          <div key={idx} className={`space-y-2.5 max-w-[90%] ${msg.role === "user" ? "ml-auto" : "mr-auto"}`}>
            {/* Sender header */}
            <div className="flex items-center gap-2 text-[10px] font-mono text-muted-foreground select-none">
              <span className="font-semibold uppercase">{msg.role === "user" ? "Developer" : "Assistant"}</span>
              <span>•</span>
              <span>Just now</span>
            </div>

            {/* Bubble */}
            <div className={`p-4 rounded-xl text-[13px] leading-relaxed shadow-sm ${
              msg.role === "user" 
                ? "bg-primary text-primary-foreground" 
                : "bg-muted/40 border border-border/80 text-foreground/90"
            }`}>
              <p className="whitespace-pre-wrap">{msg.content}</p>

              {/* References widget */}
              {msg.references && msg.references.length > 0 && (
                <div className="mt-3 pt-2.5 border-t border-border/40 flex flex-wrap items-center gap-1.5 text-[10px] text-muted-foreground font-mono">
                  <span>Context:</span>
                  {msg.references.map((ref) => (
                    <span key={ref} className="bg-card px-1.5 py-0.5 rounded border border-border/60 hover:text-rust transition-colors cursor-pointer flex items-center gap-1">
                      <FileText className="size-2.5 text-rust/80" />
                      {ref.split("/").pop()}
                    </span>
                  ))}
                </div>
              )}
            </div>

            {/* Code Snippet Box */}
            {msg.codeSnippet && (
              <div className="border border-border rounded-xl overflow-hidden bg-muted/65 shadow-sm text-xs font-mono max-w-full">
                <div className="px-3.5 py-1.5 border-b border-border/80 flex items-center justify-between text-[10px] text-muted-foreground bg-card/40">
                  <span className="font-medium">{msg.codeSnippet.file}</span>
                  <span className="uppercase text-[9px] font-bold">{msg.codeSnippet.lang}</span>
                </div>
                <pre className="p-3.5 overflow-x-auto text-[11px] leading-relaxed text-foreground/90">
                  <code>{msg.codeSnippet.code}</code>
                </pre>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Input / Quick Actions Footer */}
      <div className="p-4 border-t border-border/80 bg-card/65 backdrop-blur-sm z-10 space-y-3">
        {/* Quick Prompts */}
        <div className="flex flex-wrap gap-1.5">
          {quickActions.map((act) => (
            <button
              key={act}
              onClick={() => setInput(act)}
              className="text-[10px] font-mono px-2 py-1 rounded bg-muted/70 hover:bg-muted text-muted-foreground hover:text-foreground transition-all border border-border/40"
            >
              {act}
            </button>
          ))}
        </div>

        {/* Input Bar */}
        <form onSubmit={handleSend} className="relative flex items-center border border-border rounded-xl bg-card overflow-hidden pl-3 pr-1.5 py-1.5 focus-within:ring-2 focus-within:ring-rust/35 shadow-sm">
          <input
            type="text"
            className="flex-1 bg-transparent border-none outline-none text-xs text-foreground placeholder:text-muted-foreground/60 pr-10"
            placeholder="Ask AI anything about the codebase..."
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />
          <button
            type="submit"
            className="p-2 bg-primary text-primary-foreground hover:bg-primary/95 transition-all rounded-lg"
          >
            <Send className="size-3.5" />
          </button>
        </form>
        <div className="flex justify-between items-center text-[10px] text-muted-foreground/60 px-1 font-mono">
          <span>Vector index v1.0.4</span>
          <span>Press Enter to ask</span>
        </div>
      </div>
    </div>
  );
}
